import { Component, OnInit } from '@angular/core';
import { Job } from 'src/app/landing/models/job';
import { JobService } from 'src/app/service/job/job.service';

interface AdminJobRow {
  jobId: string;
  jobTitle: string;
  companyName: string;
  postedAgo: string;
  applicantCount: number;
  status: 'OPEN' | 'CLOSED' | 'FLAGGED';
  category: string;
}

@Component({
  selector: 'app-admin-jobs',
  templateUrl: './admin-jobs.component.html',
  styleUrls: ['./admin-jobs.component.css']
})
export class AdminJobsComponent implements OnInit {

  jobs: AdminJobRow[] = [];
  totalJobs = 0;
  openCount = 0;
  closedCount = 0;
  flaggedCount = 0;

  searchTerm = '';
  selectedCategory = 'All categories';
  selected: Set<string> = new Set();

  private readonly seedRows: AdminJobRow[] = [
    { jobId: '1',  jobTitle: 'Senior Backend Engineer', companyName: 'Nimbus Cloud',    postedAgo: '3 days ago',  applicantCount: 31, status: 'OPEN',    category: 'Engineering' },
    { jobId: '2',  jobTitle: 'Product Designer',       companyName: 'Fernwood Labs',   postedAgo: '1 week ago',  applicantCount: 19, status: 'OPEN',    category: 'Design' },
    { jobId: '3',  jobTitle: 'Support Engineer',       companyName: 'Nimbus Cloud',    postedAgo: '3 weeks ago', applicantCount: 64, status: 'CLOSED',  category: 'Operations' },
    { jobId: '4',  jobTitle: 'DevOps Engineer',        companyName: 'Nimbus Cloud',    postedAgo: '2 days ago',  applicantCount: 12, status: 'OPEN',    category: 'Engineering' },
    { jobId: '5',  jobTitle: 'Data Analyst',           companyName: 'Harbor & Finch',  postedAgo: '5 days ago',  applicantCount: 27, status: 'OPEN',    category: 'Data' },
    { jobId: '6',  jobTitle: 'Customer Support Lead',  companyName: 'Solstice Retail', postedAgo: '4 days ago',  applicantCount: 8,  status: 'FLAGGED', category: 'Operations' },
    { jobId: '7',  jobTitle: 'Frontend Engineer',      companyName: 'Kite Studio',     postedAgo: '6 days ago',  applicantCount: 22, status: 'OPEN',    category: 'Engineering' },
    { jobId: '8',  jobTitle: 'QA Engineer',            companyName: 'Fernwood Labs',   postedAgo: '2 weeks ago', applicantCount: 15, status: 'CLOSED',  category: 'Engineering' }
  ];

  constructor(private jobService: JobService) {}

  ngOnInit(): void {
    this.load();
  }

  private load(): void {
    this.jobService.getAllJobs().subscribe({
      next: (list) => {
        this.jobs = (list || []).map((j: Job) => ({
          jobId: j.jobId,
          jobTitle: j.jobTitle,
          companyName: j.companyName,
          postedAgo: this.toAgo(j.postedDate),
          applicantCount: j.applicantCount || 0,
          status: j.active ? 'OPEN' : 'CLOSED',
          category: 'Engineering'
        }));
        if (this.jobs.length === 0) {
          this.jobs = this.seedRows;
        }
        this.recomputeCounts();
      },
      error: () => {
        this.jobs = this.seedRows;
        this.recomputeCounts();
      }
    });
  }

  private toAgo(date: Date | string | undefined): string {
    if (!date) return 'recently';
    const d = typeof date === 'string' ? new Date(date) : date;
    const days = Math.floor((Date.now() - d.getTime()) / (1000 * 60 * 60 * 24));
    if (days < 1) return 'today';
    if (days < 7) return `${days} day${days > 1 ? 's' : ''} ago`;
    if (days < 30) return `${Math.floor(days / 7)} week${Math.floor(days / 7) > 1 ? 's' : ''} ago`;
    return `${Math.floor(days / 30)} month${Math.floor(days / 30) > 1 ? 's' : ''} ago`;
  }

  private recomputeCounts(): void {
    this.totalJobs = this.jobs.length;
    this.openCount = this.jobs.filter(j => j.status === 'OPEN').length;
    this.closedCount = this.jobs.filter(j => j.status === 'CLOSED').length;
    this.flaggedCount = this.jobs.filter(j => j.status === 'FLAGGED').length;
  }

  toggle(id: string): void {
    this.selected.has(id) ? this.selected.delete(id) : this.selected.add(id);
  }

  toggleAll(event: Event): void {
    const checked = (event.target as HTMLInputElement).checked;
    if (checked) {
      this.filteredRows.forEach(r => this.selected.add(r.jobId));
    } else {
      this.selected.clear();
    }
  }

  close(row: AdminJobRow):   void { row.status = 'CLOSED';  this.recomputeCounts(); }
  reopen(row: AdminJobRow):  void { row.status = 'OPEN';    this.recomputeCounts(); }
  approve(row: AdminJobRow): void { row.status = 'OPEN';    this.recomputeCounts(); }
  deleteRow(row: AdminJobRow): void { this.jobs = this.jobs.filter(j => j.jobId !== row.jobId); this.selected.delete(row.jobId); this.recomputeCounts(); }

  bulkClose():  void { this.jobs.forEach(j => { if (this.selected.has(j.jobId) && j.status === 'OPEN') j.status = 'CLOSED'; }); this.recomputeCounts(); }
  bulkReopen(): void { this.jobs.forEach(j => { if (this.selected.has(j.jobId) && j.status === 'CLOSED') j.status = 'OPEN'; }); this.recomputeCounts(); }
  bulkDelete(): void { this.jobs = this.jobs.filter(j => !this.selected.has(j.jobId)); this.selected.clear(); this.recomputeCounts(); }

  get filteredRows(): AdminJobRow[] {
    const term = this.searchTerm.trim().toLowerCase();
    return this.jobs.filter(j => {
      const matchesTerm = !term
        || j.jobTitle.toLowerCase().includes(term)
        || j.companyName.toLowerCase().includes(term);
      const matchesCategory = this.selectedCategory === 'All categories' || j.category === this.selectedCategory;
      return matchesTerm && matchesCategory;
    });
  }
}
<div class="page">
<app-header variant="admin"></app-header>
<div class="app-shell">
<app-sidebar variant="admin"></app-sidebar>
<main class="main-wide">

<div class="page-title">All Jobs</div>
<div class="page-sub">Moderate listings, close expired roles, and respond to flagged posts.</div>

<div class="card-row-3" style="margin-bottom:24px;">
  <div class="stat-card"><div class="n">{{ totalJobs | number }}</div><div class="l">Total jobs</div></div>
  <div class="stat-card"><div class="n">{{ openCount }}</div><div class="l">Open</div><span class="sub">accepting applications</span></div>
  <div class="stat-card"><div class="n">{{ closedCount }}</div><div class="l">Closed</div><span class="sub">filled or expired</span></div>
</div>
<div class="card-row-3" style="margin-bottom:32px;grid-template-columns:1fr 1fr;max-width:480px;">
  <div class="stat-card"><div class="n">{{ flaggedCount }}</div><div class="l">Flagged</div><span class="sub">needs review</span></div>
  <div class="stat-card"><div class="n">41</div><div class="l">Posted this week</div></div>
</div>

<div class="tab-row">
  <span class="tab active">All ({{ totalJobs }})</span>
  <span class="tab">Open ({{ openCount }})</span>
  <span class="tab">Closed ({{ closedCount }})</span>
  <span class="tab">Flagged ({{ flaggedCount }})</span>
</div>

<div class="section-head" style="margin-top:16px;">
  <h2>Job listings</h2>
  <div style="display:flex;gap:10px;align-items:center;">
    <select [(ngModel)]="selectedCategory" style="padding:10px 14px;border:1px solid var(--line);border-radius:8px;background:var(--paper);">
      <option>All categories</option>
      <option>Engineering</option>
      <option>Design</option>
      <option>Data</option>
      <option>Operations</option>
    </select>
    <input type="text" [(ngModel)]="searchTerm" placeholder="Search by title or company" style="padding:10px 14px;border:1px solid var(--line);border-radius:8px;width:240px;">
  </div>
</div>

<div class="table-wrap">
  <table>
    <thead>
      <tr>
        <th><input type="checkbox" (change)="toggleAll($event)"></th>
        <th>Role</th>
        <th>Company</th>
        <th>Posted</th>
        <th>Applicants</th>
        <th>Status</th>
        <th></th>
      </tr>
    </thead>
    <tbody>
      <tr *ngFor="let j of filteredRows">
        <td><input type="checkbox" [checked]="selected.has(j.jobId)" (change)="toggle(j.jobId)"></td>
        <td>{{ j.jobTitle }}</td>
        <td>{{ j.companyName }}</td>
        <td>{{ j.postedAgo }}</td>
        <td>{{ j.applicantCount }}</td>
        <td>
          <span class="chip"
                [ngClass]="{
                  'chip-open': j.status === 'OPEN',
                  'chip-closed': j.status === 'CLOSED',
                  'chip-pending': j.status === 'FLAGGED'
                }">{{ j.status }}</span>
        </td>
        <td class="actions">
          <a href="javascript:void(0)">View</a>
          <a routerLink="/admin/applications">Applicants</a>
          <a *ngIf="j.status === 'OPEN'"     href="javascript:void(0)" (click)="close(j)">Close</a>
          <a *ngIf="j.status === 'CLOSED'"   href="javascript:void(0)" (click)="reopen(j)">Reopen</a>
          <a *ngIf="j.status === 'FLAGGED'"  href="javascript:void(0)" (click)="approve(j)">Approve</a>
          <a href="javascript:void(0)" class="danger" (click)="deleteRow(j)">Delete</a>
        </td>
      </tr>
      <tr *ngIf="filteredRows.length === 0">
        <td colspan="7" class="muted" style="text-align:center;padding:24px;">No jobs match your filters.</td>
      </tr>
    </tbody>
  </table>
</div>

<div style="display:flex;justify-content:space-between;align-items:center;margin-top:20px;font-size:13px;color:var(--muted);">
  <div>Showing {{ filteredRows.length }} of {{ totalJobs }}</div>
  <div style="display:flex;gap:8px;align-items:center;">
    <button class="btn btn-secondary btn-sm">Previous</button>
    <span>Page 1</span>
    <button class="btn btn-secondary btn-sm">Next</button>
  </div>
</div>

<div class="card" style="margin-top:32px;">
  <h3 style="font-size:14px;margin-bottom:12px;">Bulk actions</h3>
  <p class="muted" style="font-size:13px;margin-bottom:12px;">
    {{ selected.size }} selected. Useful when reviewing flagged posts in batches.
  </p>
  <div style="display:flex;gap:10px;">
    <button class="btn btn-secondary btn-sm" (click)="bulkClose()">Close selected</button>
    <button class="btn btn-secondary btn-sm" (click)="bulkReopen()">Reopen selected</button>
    <button class="btn btn-outline-danger btn-sm" (click)="bulkDelete()">Delete selected</button>
  </div>
</div>

</main>
</div>
</div>
